const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laJollaPoint = ee.Geometry.Point([-117.27, 32.85]); // La Jolla Shores, CA
  const bufferDistance = 5000; // 5 km buffer to represent "near the coast"
  const analysisRegion = laJollaPoint.buffer(bufferDistance);

  const startDate = '2018-08-01';
  const endDate = '2018-08-01'; // Single day

  // 2. Data Acquisition
  const oisstCollection = ee.ImageCollection('NOAA/CDR/OISST/V2_1')
    .filterDate(startDate, endDate)
    .filterBounds(analysisRegion);

  // Check if the collection is empty
  const collectionSize = await oisstCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No OISST images found for August 1, 2018, in the specified region.");
    console.log("C1");
    return;
  }

  const sstImage = oisstCollection.first();
  const sstBand = sstImage.select('sst'); // Sea surface temperature in Celsius

  // 3. Processing & Calculation
  const scale = 3000; // OISST resolution is ~27km, 3km scale is appropriate

  // Calculate pixel count to detect C2 (no valid pixels)
  const pixelCountReducer = ee.Reducer.count();
  const pixelCount = await sstBand.reduceRegion({
    reducer: pixelCountReducer,
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('sst').getInfo();

  if (pixelCount === 0) {
    console.log("Images exist, but after processing, 0 valid pixels remain in the region.");
    console.log("C2");
    return;
  }

  // Calculate the mean SST for the region
  const meanSSTReducer = ee.Reducer.mean();
  const meanSSTResult = await sstBand.reduceRegion({
    reducer: meanSSTReducer,
    geometry: analysisRegion,
    scale: scale,
    maxPixels: 1e9
  }).get('sst').getInfo();

  // 4. Validation & Final Answer
  if (meanSSTResult === null || isNaN(meanSSTResult)) {
    console.log("Calculation resulted in Null or NaN (C3).");
    console.log("C3");
    return;
  }

  const threshold = 23; // degrees Celsius
  const exceededThreshold = meanSSTResult > threshold;

  console.log(`Date: ${startDate}`);
  console.log(`Location: La Jolla, CA (5km buffer)`);
  console.log(`Mean SST: ${meanSSTResult.toFixed(2)} °C`);
  console.log(`Valid Pixels in region: ${pixelCount}`);
  console.log(`Threshold: ${threshold} °C`);

  if (exceededThreshold) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
